<?php
/**
 * Generated by Playground's --experimental-posix-kernel browser mode.
 * Reads constants from the JSON store next to this file and define()s
 * them on every request. Identical to the CLI's mu-plugin — both modes
 * write the same JSON via `KernelLimitedPHPApi.defineConstant`.
 */
$store = __DIR__ . '/0-playground-defines.json';
if (!file_exists($store)) {
    return;
}
$entries = json_decode((string) file_get_contents($store), true);
if (!is_array($entries)) {
    return;
}
foreach ($entries as $name => $value) {
    if (defined($name)) {
        continue;
    }
    define($name, $value);
}
